(()=>{'use strict';const toggle=document.querySelector('.menu-toggle'),nav=document.querySelector('#mobile-nav');toggle.addEventListener('click',()=>{const open=toggle.getAttribute('aria-expanded')!=='true';toggle.setAttribute('aria-expanded',String(open));toggle.setAttribute('aria-label',open?'Затворете менюто':'Отворете менюто');nav.hidden=!open});document.addEventListener('keydown',e=>{if(e.key==='Escape'&&!nav.hidden){nav.hidden=true;toggle.setAttribute('aria-expanded','false');toggle.setAttribute('aria-label','Отворете менюто');toggle.focus()}});nav.querySelectorAll('a').forEach(a=>a.addEventListener('click',()=>{nav.hidden=true;toggle.setAttribute('aria-expanded','false');toggle.setAttribute('aria-label','Отворете менюто')}));window.matchMedia('(min-width:861px)').addEventListener('change',event=>{if(event.matches){nav.hidden=true;toggle.setAttribute('aria-expanded','false');toggle.setAttribute('aria-label','Отворете менюто')}});document.querySelectorAll('.quote-form').forEach(form=>{const select=form.elements.insurance,fields=form.querySelector('.go-fields:not(.kasko-fields)'),kasko=form.querySelector('.kasko-fields'),result=form.querySelector('.form-result');function sync(){const go=select.value==='grazhdanska-otgovornost'||(!kasko&&select.value==='kasko'),car=!!kasko&&select.value==='kasko';fields.hidden=!go;fields.disabled=!go;if(kasko){kasko.hidden=!car;kasko.disabled=!car}result.hidden=true}select.addEventListener('change',sync);sync();form.addEventListener('input',()=>{form.querySelector('.form-empty')?.remove();if(!form.classList.contains('is-sent'))result.hidden=true});form.addEventListener('submit',e=>{e.preventDefault();const filled=[...form.querySelectorAll('input,textarea')].some(el=>!el.closest(':disabled')&&el.value.trim());let empty=form.querySelector('.form-empty');if(!filled){if(!empty){empty=document.createElement('p');empty.className='form-empty';empty.setAttribute('role','alert');empty.textContent='Попълнете поне едно поле, за да прегледате данните.';form.querySelector('[type=submit]').before(empty)}return}if(empty)empty.remove();let summary=result.querySelector('.submitted-summary');if(!summary){summary=document.createElement('dl');summary.className='submitted-summary';result.querySelector('p').after(summary)}summary.replaceChildren();const labels={insurance:'Застраховка',registration:'Регистрационен номер',engine:'Обем на двигателя (см³)',age:'Възраст на собственика',model:'Марка и модел',year:'Година на производство',value:'Приблизителна стойност',phone:'Телефон',message:'Съобщение'};for(const [key,value] of new FormData(form)){if(!String(value).trim())continue;const dt=document.createElement('dt'),dd=document.createElement('dd');dt.textContent=labels[key]||key;dd.textContent=key==='insurance'?select.selectedOptions[0].textContent:value;summary.append(dt,dd)}form.classList.add('is-sent');result.hidden=false;result.scrollIntoView({behavior:matchMedia('(prefers-reduced-motion: reduce)').matches?'auto':'smooth',block:'nearest'});result.focus({preventScroll:true})});form.querySelector('[data-reset]').addEventListener('click',()=>{form.reset();form.classList.remove('is-sent');sync();select.focus()})})})();
(()=>{'use strict';const bar=document.querySelector('.mobile-call');if(!bar||!('IntersectionObserver'in window))return;const intro=document.querySelector('main section');const watched=[...document.querySelectorAll('a[href^="tel:+359"]:not(.mobile-call)'),...(intro?(intro.querySelector('.button,.claim-button')?intro.querySelectorAll('.button,.claim-button,.sub-link,.text-button'):[intro]):[])];const inView=new Set();bar.classList.add('is-resting');const observer=new IntersectionObserver(entries=>{entries.forEach(e=>e.isIntersecting?inView.add(e.target):inView.delete(e.target));bar.classList.toggle('is-resting',inView.size>0)});watched.forEach(el=>observer.observe(el));if(!watched.length)bar.classList.remove('is-resting')})();
